#!/usr/bin/env python3
"""Renders README.md from config/readme.template.md + config/profile.json + assets/generated/resolved.json.

README.md is a generated file: edit config/profile.json or config/readme.template.md instead.
Card links point only at things that were verified:
  * a public repository that make_stats.py matched through the GitHub API (resolved.json), or
  * the live URL you put in the config.
A project with neither is shown as a plain, unlinked card. The profile URL is never used as a stand-in.
"""
import json
import os

from lib import ROOT, esc, load_config

RAW = "https://raw.githubusercontent.com/{handle}/{handle}/main"


def resolved():
    p = os.path.join(ROOT, "assets", "generated", "resolved.json")
    try:
        return json.load(open(p, encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def pic(raw, wide, narrow, width, alt, extra=""):
    return (f'<picture><source media="(max-width: 700px)" srcset="{raw}/{narrow}">'
            f'<img src="{raw}/{wide}" width="{width}" {extra}alt="{esc(alt)}"></picture>')


def sec_pic(raw, name, alt):
    return pic(raw, f"assets/sec-{name}.svg", f"assets/sec-{name}-narrow.svg", "100%", alt)


def hero(cfg, raw):
    h = cfg["handle"]
    photo = f'<img src="https://github.com/{h}.png?size=460" width="30%" align="top" alt="{esc(cfg["name"])}, profile photo">'
    term = pic(raw, "assets/hero-terminal.svg", "assets/hero-terminal-narrow.svg", "68%",
               f'{cfg["name"]}: {cfg["role"]}. {cfg["degree"]}.', 'align="top" ')
    return f'<div align="center">\n\n{photo} {term}\n\n</div>'


def block(img_html):
    return f'<div align="center">\n\n{img_html}\n\n</div>'


def projects(cfg, raw, res):
    cards = []
    for p in cfg["projects"]:
        s = p["slug"]
        href = (res.get(s) or {}).get("url") or p.get("live")
        img = pic(raw, f"assets/generated/proj-{s}.svg", f"assets/generated/proj-{s}-narrow.svg", "49%",
                  f'{p["title"]}: {p["blurb"]}.')
        title = esc(f'{p["title"]}: {p["blurb"]}')
        cards.append(f'<a href="{href}" title="{title}">{img}</a>' if href else img)
    rows = []
    for i in range(0, len(cards), 2):
        rows.append("<p>\n" + "&nbsp;".join(cards[i:i + 2]) + "\n</p>")
    repo_links = [f'<a href="{res[p["slug"]]["url"]}">{esc(p["title"])}</a>' for p in cfg["projects"] if p["slug"] in res]
    live_links = [f'<a href="{p["live"]}">{esc(p["title"])} ↗</a>' for p in cfg["projects"] if p.get("live")]
    parts = []
    if repo_links:
        parts.append("<code>repos</code> " + " · ".join(repo_links))
    if live_links:
        parts.append("<code>live</code> " + " · ".join(live_links))
    parts.append(f'<a href="https://github.com/{cfg["handle"]}?tab=repositories">all repositories ↗</a>')
    sec = sec_pic(raw, "projects", "~/projects featured")
    return (f'{sec}\n\n' + "\n".join(rows) +
            '\n\n<div align="center">\n<sub>' + " &nbsp;&nbsp; ".join(parts) + '</sub>\n</div>')


def contact(cfg, raw):
    L = cfg["links"]
    hrefs = {"github": L.get("github"), "linkedin": L.get("linkedin"),
             "email": f'mailto:{L["email"]}' if L.get("email") and not L["email"].startswith("mailto:") else L.get("email"),
             "portfolio": L.get("portfolio")}
    btns = [f'<a href="{h}"><img src="{raw}/assets/btn-{k}.svg" height="40" alt="{k.capitalize()}"></a>'
            for k, h in hrefs.items() if h]
    return (sec_pic(raw, "contact", "~/contact") + "\n\n"
            '<div align="center">\n\n' + "\n&nbsp;&nbsp;&nbsp;\n".join(btns) + "\n\n</div>")


def main():
    cfg = load_config()
    raw = RAW.format(handle=cfg["handle"])
    res = resolved()
    tpl = open(os.path.join(ROOT, "config", "readme.template.md"), encoding="utf-8").read()
    parts = {
        "HERO": hero(cfg, raw),
        "STATS": block(pic(raw, "assets/generated/stats.svg", "assets/generated/stats-narrow.svg", "100%",
                           f'GitHub statistics for {cfg["handle"]}')),
        "CONTRIBUTIONS": block(f'<img src="{raw}/assets/generated/contributions.svg" width="100%" '
                               f'alt="Contribution graph for the last 12 months with a runner crossing it.">'),
        "PROJECTS": projects(cfg, raw, res),
        "TOOLCHAIN": sec_pic(raw, "toolchain", "~/toolchain") + "\n\n" +
                     block(pic(raw, "assets/tech-stack.svg", "assets/tech-stack-narrow.svg", "100%",
                               "Technologies: " + ", ".join(n for g in cfg["tech_groups"] for _, n in g["items"]))),
        "CONTACT": contact(cfg, raw),
    }
    for k, v in parts.items():
        tpl = tpl.replace("{{" + k + "}}", v)
    out = "<!-- GENERATED by .github/scripts/make_readme.py. Edit config/profile.json or config/readme.template.md instead. -->\n" + tpl
    path = os.path.join(ROOT, "README.md")
    old = open(path, encoding="utf-8").read() if os.path.exists(path) else None
    if old != out:
        open(path, "w", encoding="utf-8", newline="\n").write(out)
        print("README.md updated")
    else:
        print("README.md unchanged")


if __name__ == "__main__":
    main()
